// Hand-written (NOT autogenerated). Guards the id-type String() rendering that
// tools/ulsdkbuild emits, and in particular that fmt.Sprintf("%v", id) on a
// *value* uses it — the generated API interpolates ids into URLs that way, and
// a pointer-receiver String() would be silently ignored for values.

package id

import (
	"fmt"
	"testing"
)

func sixteenBytes() []byte {
	return []byte{
		0x05, 0x00, 0x12, 0xfc, 0x71, 0x2e, 0x84, 0xab,
		0x47, 0xff, 0x85, 0xc9, 0xe2, 0x3c, 0x07, 0x6e,
	}
}

const sixteenUUID = "050012fc-712e-84ab-47ff-85c9e23c076e"

func TestObjectIdString(t *testing.T) {
	o := ObjectId{B: sixteenBytes()}
	if got := o.String(); got != sixteenUUID {
		t.Errorf("String() = %q, want %q", got, sixteenUUID)
	}
}

func TestObjectIdValueFormatsViaStringer(t *testing.T) {
	// The critical case: a VALUE (not pointer) passed to fmt must use String().
	o := ObjectId{B: sixteenBytes()}
	if got := fmt.Sprintf("%v", o); got != sixteenUUID {
		t.Errorf("Sprintf(%%v, value) = %q, want %q", got, sixteenUUID)
	}
	if got := fmt.Sprintf("%s", o); got != sixteenUUID {
		t.Errorf("Sprintf(%%s, value) = %q, want %q", got, sixteenUUID)
	}
}

func TestObjectIdStringShortBytesNoPanic(t *testing.T) {
	// Zero value has nil B; must not panic, just render the raw hex.
	var o ObjectId
	if got := o.String(); got != "" {
		t.Errorf("zero-value String() = %q, want empty", got)
	}
	o = ObjectId{B: []byte{0xde, 0xad}}
	if got := o.String(); got != "dead" {
		t.Errorf("short String() = %q, want %q", got, "dead")
	}
}

func TestOtherIdTypesString(t *testing.T) {
	b := sixteenBytes()
	if got := (StreamId{B: b}).String(); got != sixteenUUID {
		t.Errorf("StreamId.String() = %q, want %q", got, sixteenUUID)
	}
	if got := (ContentId{B: b}).String(); got != sixteenUUID {
		t.Errorf("ContentId.String() = %q, want %q", got, sixteenUUID)
	}
	if got := (GenericId{B: b}).String(); got != sixteenUUID {
		t.Errorf("GenericId.String() = %q, want %q", got, sixteenUUID)
	}
}
